changeSet.sql:
-- ---- stamp_chunks_on_manifest_delete CREATE OR REPLACE FUNCTION nexus.stamp_chunks_on_manifest_delete() RETURNS trigger LANGUAGE plpgsql AS $function$ BEGIN -- Lock the chunk rows first, in key order: two writers that drop the last two owners of a shared -- chunk serialize here (the second blocks until the first commits, then reads its committed -- orphaned_at), and writers that share several chunks take their locks in the same order, so two -- of these triggers cannot deadlock on chunk rows. The key list is the same as the upsert's. PERFORM 1 FROM nexus.chunks c JOIN (SELECT DISTINCT tenant_id, collection, chash, embedding_model FROM old_rows) o ON o.tenant_id = c.tenant_id AND o.collection = c.collection AND o.chash = c.chash AND o.embedding_model = c.embedding_model ORDER BY c.tenant_id, c.collection, c.chash FOR NO KEY UPDATE OF c;
-- Record the orphaning of EVERY dropped key (nexus-z0o2p.29: no last_written_at filter). A chunk already recorded within the hour is -- skipped by the DO UPDATE's WHERE. Driven from the chunk rows, so a key with no chunk (the -- foreign key would refuse it) records nothing. A key the same transaction inserts again is cleared by -- the INSERT trigger. -- RDR-225: the orphaned-at row carries the chunk's embedding_model (the four-column chunk foreign key); -- its own primary key, and so this arbiter, stays (tenant_id, collection, chash). INSERT INTO nexus.chunk_orphaned_at AS q (tenant_id, collection, chash, orphaned_at, embedding_model) SELECT c.tenant_id, c.collection, c.chash, now(), c.embedding_model FROM nexus.chunks c JOIN (SELECT DISTINCT tenant_id, collection, chash, embedding_model FROM old_rows) o ON o.tenant_id = c.tenant_id AND o.collection = c.collection AND o.chash = c.chash AND o.embedding_model = c.embedding_model ORDER BY c.tenant_id, c.collection, c.chash ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET orphaned_at = EXCLUDED.orphaned_at WHERE q.orphaned_at < now() - interval '1 hour'; RETURN NULL; END; $function$;
-- ---- stamp_chunks_on_manifest_update CREATE OR REPLACE FUNCTION nexus.stamp_chunks_on_manifest_update() RETURNS trigger LANGUAGE plpgsql AS $function$ BEGIN -- The keys the statement dropped are the old keys minus the new keys: a row that keeps its -- (tenant, collection, chash), whatever else changed, drops nothing; one that moves position and -- chash together drops the old chash. Same lock, same upsert, same guard as the DELETE trigger. PERFORM 1 FROM nexus.chunks c JOIN (SELECT tenant_id, collection, chash, embedding_model FROM old_rows EXCEPT SELECT tenant_id, collection, chash, embedding_model FROM new_rows) o ON o.tenant_id = c.tenant_id AND o.collection = c.collection AND o.chash = c.chash AND o.embedding_model = c.embedding_model ORDER BY c.tenant_id, c.collection, c.chash FOR NO KEY UPDATE OF c;
-- RDR-225: carries the chunk's embedding_model; the arbiter stays the table's own three-column key. INSERT INTO nexus.chunk_orphaned_at AS q (tenant_id, collection, chash, orphaned_at, embedding_model) SELECT c.tenant_id, c.collection, c.chash, now(), c.embedding_model FROM nexus.chunks c JOIN (SELECT tenant_id, collection, chash, embedding_model FROM old_rows EXCEPT SELECT tenant_id, collection, chash, embedding_model FROM new_rows) o ON o.tenant_id = c.tenant_id AND o.collection = c.collection AND o.chash = c.chash AND o.embedding_model = c.embedding_model ORDER BY c.tenant_id, c.collection, c.chash ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET orphaned_at = EXCLUDED.orphaned_at WHERE q.orphaned_at < now() - interval '1 hour';
-- A chunk this statement gave an owner (a key of new_rows not in old_rows) carries no record: lock the -- record rows in key order (the order the upserts take them in), then delete them. PERFORM 1 FROM nexus.chunk_orphaned_at q JOIN (SELECT tenant_id, collection, chash FROM new_rows EXCEPT SELECT tenant_id, collection, chash FROM old_rows) n ON n.tenant_id = q.tenant_id AND n.collection = q.collection AND n.chash = q.chash ORDER BY q.tenant_id, q.collection, q.chash FOR UPDATE OF q; DELETE FROM nexus.chunk_orphaned_at q USING (SELECT tenant_id, collection, chash FROM new_rows EXCEPT SELECT tenant_id, collection, chash FROM old_rows) n WHERE n.tenant_id = q.tenant_id AND n.collection = q.collection AND n.chash = q.chash; RETURN NULL; END; $function$;
-- ---- clear_orphaned_on_manifest_insert CREATE OR REPLACE FUNCTION nexus.clear_orphaned_on_manifest_insert() RETURNS trigger LANGUAGE plpgsql AS $function$ BEGIN -- A chunk key this statement inserted has an owner: its orphaning record, if any, is no longer true. The -- record rows are locked in key order first (the order the stamp upserts take them in), then deleted. A -- record another transaction wrote and has not committed is invisible here and may commit on an owned -- chunk: harmless (an owned chunk is not reapable) and refreshed by the next drop. Tenant equality in the -- join: the only barrier for a role that bypasses RLS. Never touches nexus.chunks. PERFORM 1 FROM nexus.chunk_orphaned_at q JOIN (SELECT DISTINCT tenant_id, collection, chash FROM new_rows) n ON n.tenant_id = q.tenant_id AND n.collection = q.collection AND n.chash = q.chash ORDER BY q.tenant_id, q.collection, q.chash FOR UPDATE OF q; DELETE FROM nexus.chunk_orphaned_at q USING (SELECT DISTINCT tenant_id, collection, chash FROM new_rows) n WHERE n.tenant_id = q.tenant_id AND n.collection = q.collection AND n.chash = q.chash; RETURN NULL; END; $function$;
REVOKE EXECUTE ON FUNCTION nexus.clear_orphaned_on_manifest_insert() FROM PUBLIC;
CREATE TRIGGER trg_catalog_chunks_clear_orphan_on_insert AFTER INSERT ON nexus.catalog_document_chunks REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION nexus.clear_orphaned_on_manifest_insert();

rollback.sql:
DROP TRIGGER IF EXISTS trg_catalog_chunks_clear_orphan_on_insert ON nexus.catalog_document_chunks; DROP FUNCTION IF EXISTS nexus.clear_orphaned_on_manifest_insert();
